1	import { type DragEvent, type MouseEvent, useRef } from 'react';
2	import type { FolderChild } from '@cipherbox/core';
3	import { useUploadStore } from '../../stores/upload.store';
4	import type { PerFileUpload } from '../../stores/upload.store';
5	import { FileListItem, type DragItem } from './FileListItem';
6	import { UploadListItem } from './UploadListItem';
7	import { ParentDirRow } from './ParentDirRow';
8	
9	/**
10	 * Virtual entry representing an in-progress upload in the sorted file list.
11	 * The `_uploading` flag discriminates it from real FolderChild items.
12	 */
13	type UploadVirtualEntry = {
14	  type: 'file';
15	  id: string;
16	  name: string;
17	  fileMetaIpnsName: '';
18	  createdAt: number;
19	  modifiedAt: number;
20	  _uploading: true;
21	};
22	
23	type FileListProps = {
24	  /** Items to display (files and folders) */
25	  items: FolderChild[];
26	  /** Set of currently selected item IDs */
27	  selectedIds: Set<string>;
28	  /** Parent folder ID (for drag operations) */
29	  parentId: string;
30	  /** Parent folder's decrypted AES-256 key (for resolving file sizes) */
31	  folderKey: Uint8Array | null;
32	  /** Whether to show [..] PARENT_DIR row (non-root folders) */
33	  showParentRow?: boolean;
34	  /** Callback when [..] row is clicked to navigate up */
35	  onNavigateUp?: () => void;
36	  /** Callback when an item is selected (with modifier key info) */
37	  onSelect: (
38	    itemId: string,
39	    event: { ctrlKey: boolean; shiftKey: boolean; metaKey: boolean }
40	  ) => void;
41	  /** Callback to select/deselect all items */
42	  onSelectAll: () => void;
43	  /** Callback when navigating into a folder */
44	  onNavigate: (folderId: string) => void;
45	  /** Callback when context menu is requested */
46	  onContextMenu: (event: MouseEvent, item: FolderChild) => void;
47	  /** Callback when drag starts */
48	  onDragStart: (event: DragEvent, item: FolderChild) => void;
49	  /** Callback when items are dropped onto a folder */
50	  onDropOnFolder?: (items: DragItem[], sourceParentId: string, destFolderId: string) => void;
51	  /** Callback when external files are dropped onto a folder */
52	  onExternalFileDrop?: (files: File[], destFolderId: string) => void;
53	  /** Callback to re-trigger upload for a failed file (retry button in UploadListItem) */
54	  onRetryUpload?: (file: File) => void;
55	};
56	
57	/**
58	 * Sort items: folders first, then files, both alphabetically.
59	 */
60	function sortItems(items: FolderChild[]): FolderChild[] {
61	  return [...items].sort((a, b) => {
62	    // Folders come first
63	    if (a.type === 'folder' && b.type !== 'folder') return -1;
64	    if (a.type !== 'folder' && b.type === 'folder') return 1;
65	
66	    // Within same type, sort alphabetically (case-insensitive)
67	    return a.name.localeCompare(b.name, undefined, { sensitivity: 'base' });
68	  });
69	}
70	
71	/**
72	 * File list component displaying files and folders in a columnar layout.
73	 *
74	 * Renders items sorted by type (folders first) then alphabetically.
75	 * Supports selection, navigation, context menu, and drag operations.
76	 *
77	 * @example
78	 * ```tsx
79	 * function FileBrowser() {
80	 *   const { currentFolder } = useFolderNavigation();
81	 *   const [selectedId, setSelectedId] = useState<string | null>(null);
82	 *
83	 *   return (
84	 *     <FileList
85	 *       items={currentFolder?.children ?? []}
86	 *       selectedId={selectedId}
87	 *       parentId={currentFolder?.id ?? 'root'}
88	 *       onSelect={setSelectedId}
89	 *       onNavigate={navigateTo}
90	 *       onContextMenu={handleContextMenu}
91	 *       onDragStart={handleDragStart}
92	 *     />
93	 *   );
94	 * }
95	 * ```
96	 */
97	export function FileList({
98	  items,
99	  selectedIds,
100	  parentId,
101	  folderKey,
102	  showParentRow,
103	  onNavigateUp,
104	  onSelect,
105	  onSelectAll,
106	  onNavigate,
107	  onContextMenu,
108	  onDragStart,
109	  onDropOnFolder,
110	  onExternalFileDrop,
111	  onRetryUpload,
112	}: FileListProps) {
113	  // Subscribe to upload entries for this folder only (IDs + status, not progress).
114	  // Progress updates re-render individual UploadListItem rows via their own fine-grained selectors.
115	  // Custom equality via ref prevents re-renders on every progress tick.
116	  type UploadEntry = { id: string; filename: string; status: PerFileUpload['status'] };
117	  const prevEntriesRef = useRef<UploadEntry[]>([]);
118	  const uploadEntries = useUploadStore((s) => {
119	    const entries: UploadEntry[] = [];
120	    for (const f of s.files.values()) {
121	      if (f.targetFolderId === parentId) {
122	        entries.push({ id: f.id, filename: f.filename, status: f.status });
123	      }
124	    }
125	    const prev = prevEntriesRef.current;
126	    if (
127	      prev.length === entries.length &&
128	      prev.every((p, i) => p.id === entries[i].id && p.status === entries[i].status)
129	    ) {
130	      return prev;
131	    }
132	    prevEntriesRef.current = entries;
133	    return entries;
134	  });
135	
136	  // Create virtual entries for sorting alongside real items
137	  const uploadVirtualEntries: UploadVirtualEntry[] = uploadEntries.map((f) => ({
138	    type: 'file' as const,
139	    id: f.id,
140	    name: f.filename,
141	    fileMetaIpnsName: '' as const,
142	    createdAt: 0,
143	    modifiedAt: 0,
144	    _uploading: true as const,
145	  }));
146	
147	  // Prevent duplicate rows: when a real file already exists, hide the completing
148	  // upload row instead of the real file row. This ensures the real file is never
149	  // removed from the DOM during the 1-second completion flash. (Pitfall 5)
150	  const realFileNames = new Set(
151	    items.filter((item) => item.type === 'file').map((item) => item.name)
152	  );
153	  const completeUploadIds = new Set(
154	    uploadEntries
155	      .filter((e) => e.status === 'complete' && realFileNames.has(e.filename))
156	      .map((e) => e.id)
157	  );
158	  const filteredUploadEntries = uploadVirtualEntries.filter(
159	    (entry) => !completeUploadIds.has(entry.id)
160	  );
161	
162	  // Merge and sort all items together
163	  const allItems = [...items, ...filteredUploadEntries];
164	  const sortedItems = sortItems(allItems as FolderChild[]);
165	
166	  // Select-all uses real item count only (upload rows are not selectable)
167	  const allSelected = items.length > 0 && selectedIds.size === items.length;
168	
169	  return (
170	    <div className="file-list" role="grid">
171	      {/* Header row */}
172	      <div className="file-list-header" role="row">
173	        <div className="file-list-header-name" role="columnheader">
174	          <span
175	            className="file-list-header-checkbox"
176	            onClick={onSelectAll}
177	            role="checkbox"
178	            aria-checked={allSelected}
179	            aria-label={allSelected ? 'Deselect all' : 'Select all'}
180	            tabIndex={0}
181	            onKeyDown={(e) => {
182	              if (e.key === 'Enter' || e.key === ' ') {
183	                e.preventDefault();
184	                onSelectAll();
185	              }
186	            }}
187	          >
188	            {allSelected ? '[x]' : '[ ]'}
189	          </span>
190	          [NAME]
191	        </div>
192	        <div className="file-list-header-size" role="columnheader">
193	          [SIZE]
194	        </div>
195	        <div className="file-list-header-date" role="columnheader">
196	          [MODIFIED]
197	        </div>
198	        {/* Empty header cell for mobile action column - hidden on desktop via CSS */}
199	        <div className="file-list-header-actions" aria-hidden="true" />
200	      </div>
201	
202	      {/* Item rows */}
203	      <div className="file-list-body" role="rowgroup">
204	        {showParentRow && onNavigateUp && <ParentDirRow onActivate={onNavigateUp} />}
205	        {sortedItems.map((item) =>
206	          '_uploading' in item ? (
207	            <UploadListItem key={item.id} fileId={item.id} onRetry={onRetryUpload} />
208	          ) : (
209	            <FileListItem
210	              key={item.id}
211	              item={item}
212	              isSelected={selectedIds.has(item.id)}
213	              parentId={parentId}
214	              selectedIds={selectedIds}
215	              allItems={items}
216	              folderKey={folderKey}
217	              onSelect={onSelect}
218	              onNavigate={onNavigate}
219	              onContextMenu={onContextMenu}
220	              onDragStart={onDragStart}
221	              onDrop={
222	                onDropOnFolder && item.type === 'folder'
223	                  ? (dragItems, sourceParentId) =>
224	                      onDropOnFolder(dragItems, sourceParentId, item.id)
225	                  : undefined
226	              }
227	              onExternalFileDrop={item.type === 'folder' ? onExternalFileDrop : undefined}
228	            />
229	          )
230	        )}
231	      </div>
232	    </div>
233	  );
234	}
