file.content:
/* Progress bar track */
.upload-inline-progress-track {
  height: 3px;
  background-color: var(--color-border-dim);
  overflow: hidden;
  width: 100%;
}

/* Progress bar fill */
.upload-inline-progress-fill {
  height: 100%;
  background-color: var(--color-green-primary);
  transition: width 0.2s ease;
}

.upload-inline-progress-fill[data-status='complete'] {
  background-color: var(--color-green-primary);
}

.upload-inline-progress-fill[data-status='error'] {
  background-color: var(--color-error);
}

/* Encrypting pulse animation */
@keyframes upload-inline-pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.4;
  }
}

.upload-inline-progress-track--pulse .upload-inline-progress-fill {
  width: 100% !important;
  animation: upload-inline-pulse 1.5s ease-in-out infinite;
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  .upload-inline-progress-fill,
  .upload-inline-progress-track--pulse .upload-inline-progress-fill {
    animation: none;
    transition: none;
  }
}

/* Action buttons container -- aligns buttons to the right within the date column */

